function load$GridReport$(g) {
	g.add_onRender(on$GridReport$Render);
	g.add_commandEvent(on$GridReport$ExecuteCommand);
}
function dispose$GridReport$(g) {
	try {g.remove_commandEvent(on$GridReport$ExecuteCommand);} catch (ex) {}
	try {g.remove_onRender(on$GridReport$Render);} catch (ex) {}
}
function on$GridReport$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender;
	switch (action) {
		case 'ViewDetail':
			/* yc 457
-	Tài khoản 154, 241: khi nhấn xem chi tiết: trả về báo cáo Bảng cân đối phát sinh của các công trình vụ việc.
-	Thêm nút “Xem sổ chi tiết”: trả về báo cáo Sổ chi tiết của 1 tài khoản

ref: 
@targetFields = các trường trên filter của báo cáo drilldown
@specMap = các trường đặc biệt (lấy từ trường khác tên của filter báo cáo, hoặc lấy giá trị khác). Array[0] = tên trường cần lấy trên filter, Array[1] = giá trị default
@overwriteMap = các trường có ở filter báo cáo, nhưng cần chép đè giá trị khác khi drilldown
			*/
			e.type.cancelEvent = true;


			var url =  '&Url;', ftk = $func.trim(g._getItemValue(g._activeRow, g._getColumnOrder('&k;')))
				, targetFields =  $func.dataFieldName('tk,ten_tk%l,date_from,date_to,date_open,ma_dvcs,chon_tt,mau_bc,ngay_ky,nguoi_lap,rpt_margin_left', g._language)
				, specMap = {date_from : ['ngay1', null], date_to: ['ngay2', null], chon_tt: ['', '1'], date_open: ['', null] }

			if (!ftk) return;
			if (e.type.Value == '10' ) {
				url = url.replace('rpt_glsocttk', 'rpt_covvcd1');
				targetFields = $func.dataFieldName('ngay1,ngay2,tk,ten_tk%l,vu_viec_me,ten_vv_me%l,vu_viec,ten_vv%l,nhom_vv1,ten_nh_1%l,nhom_vv2,ten_nh_2%l,nhom_vv3,ten_nh_3%l,ma_dvcs,mau_bc,nh_theo,tt_sx1,tt_sx2,tt_sx3,ngay_ky,nguoi_lap,rpt_margin_left', g._language);
				specMap =  {nh_theo: ['', 0], tt_sx1: ['', 0], tt_sx2: ['', 0], tt_sx3: ['', 0]}
			}
			var overwriteMap = {
				mau_bc: Array.contains(['001', '011', '021'], $func.findMemvar('mau_bc', g._memvars).NewValue) ? '10' : '20',
				tk: ftk
			}	

			g._$result  = 	
			targetFields
				.split(',')
				.map(function(field) {return $func.trim(field)})
				.map(function(field) {
					var k = field, v = '', specV = ''
					if (overwriteMap[field]) {
						k = '', specV = overwriteMap[field];
					}
					if (specMap[field]) {
						k = specMap[field][0];
						specV = specMap[field][1];
					}
					if (k) v =  $func.findMemvar(k, g._memvars) //g._memvars.find(function(obj) {return obj.Name == k}); 
					v = v ? v.NewValue : specV;
					return {Name:field, Value: v}
				})
			console.log(g._$result);
			g._navigate(g._activeCell, url);
			break;	
		default:
			break;
	}
}
function passQueryParameters(g) {&Parameter;	
	var session = {Memvar: g._$result, Script: 'this._convection = true;'&Session;};
	g._passParameter(session);
}

function setGridHiddenFields(g, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {    
		g._setColumnVisible(g._getColumnOrder($func.trim(a[i])), !v);
	}
}

function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}


function on$GridReport$Render(sender, eventArgs) {
	var g = eventArgs.grid;  
	if (g._hiddenFields) {
		var a = g._hiddenFields, h = '';
		for (var i = 0; i < a.length; i++) {
			setGridHiddenFields(g, a[i].Fields, a[i].Value);
			if (a[i].Value) h += (h == '' ? '' : ',') + a[i].Fields;
		}
		g._externalHiddenFields = h;
	}

	setColorWithCondition(g, 'systotal', '1', '', 'bold', '')
}
function beforeDrillDown(g) {
	var isCancel = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn)));
	g._args_r = g._activeRow;

	if (!isCancel) {
		if (!g._$xem_tk_nh && g._getItemValue(g._activeRow, g._getColumnOrder('xloai_tk')) == 1) {
			if ($func.trim(g._getItemValue(g._activeRow, g._getColumnOrder('&k;')))) g._navigate(g._activeCell, '&Url1;');
			g._args.cancelEvent = true;
			return;
		}
		if (g._getItemValue(g._activeRow, g._getColumnOrder('xloai_tk')) == 2) {
			if ($func.trim(g._getItemValue(g._activeRow, g._getColumnOrder('&k;')))) g._navigate(g._activeCell, '&Url2;');
			g._args.cancelEvent = true;
			return;
		}
		if (g._getItemValue(g._activeRow, g._getColumnOrder('xloai_tk')) == 3) {
			if ($func.trim(g._getItemValue(g._activeRow, g._getColumnOrder('&k;')))) g._navigate(g._activeCell, '&Url3;');
			g._args.cancelEvent = true;
			return;
		}
	}

	g._args.cancelEvent = isCancel;
}
function passQueryParameters$1(g) {
	var a = [];
	for (var i = 0; i < g._memvars.length; i++) {
		if (g._memvars[i].Name != 'xem_tk_nh' && g._memvars[i].Name != 'tk_1') 
			Array.add(a, {Name: g._memvars[i].Name, Value: g._memvars[i].NewValue});
	}

	Array.add(a, {Name: 'tk_1', Value: g._getItemValue(g._args_r, g._getColumnOrder('tk'))});
	Array.add(a, {Name: 'xem_tk_nh', Value: true});

	var session = {Memvar: a, Script: 'this._convection = true;'&Session;};
	g._passParameter(session);
}
function passQueryParameters$2(g) {
	var a = [&Memvar;];
	for (var i = 0; i < g._memvars.length; i++) {
		if (g._memvars[i].Name == 'ngay1') 
			Array.add(a, {Name: 'tu_ngay', Value: g._memvars[i].NewValue});
		if (g._memvars[i].Name == 'ngay2') 
			Array.add(a, {Name: 'den_ngay', Value: g._memvars[i].NewValue});
		if (g._memvars[i].Name == 'ma_dvcs') 
			Array.add(a, {Name: 'ma_dvcs', Value: g._memvars[i].NewValue});
	}

	Array.add(a, {Name: 'tk', Value: g._getItemValue(g._args_r, g._getColumnOrder('tk'))});

	var session = {Memvar: a, Script: 'this._convection = true;'&Session;};
	g._passParameter(session);
}
function setColorWithCondition(g, field, condition, color, bold, italic) {
		var iC	
		try {iC = g._getColumnOrder(field);				
			var r = g._rowCount;
			var i;
			for (i = 1; i <= r; i++) {
					if (g._getItemValue(i, iC) == condition) {
							setColor4Row(g, i, color);
							setFont4Row(g, i, bold, italic);
					}
			}
		}
		catch (err){}
}
function setColor4Row(g, rNumber, color) {
		var c = g._columnCount;
		var i;
		var o;
		for (i = 1; i <= c; i++) {
				o = g._getItem(rNumber, i);
				if (color != '') {
					//	o.style.color = color;
						$get(g.get_id()+ '_gridCell_' + rNumber.toString() + '.' +  i.toString()).style.backgroundColor = color;

					//	o.style.backgroundColor = color;

				}
		}
}
function setFont4Row(g, rNumber, bold, italic) {
		var c = g._columnCount;
		var i;
		var o;
		for (i = 1; i <= c; i++) {
				o = g._getItem(rNumber, i);
				if (bold != '') {
						o.style.fontWeight = bold;
				}
				if (italic != '') {
						o.style.fontStyle = italic;
				}
		}
}
